sudo apt install -y nginx
sudo tee /etc/nginx/conf.d/app.conf >/dev/null <<'EOF'
upstream app_backend { server 127.0.0.1:8080 max_fails=3 fail_timeout=10s; }
server {
  listen 80;
  server_name app.local;
  location / {
    proxy_pass http://app_backend;
    proxy_set_header Host $host;
    proxy_set_header X-Real-IP $remote_addr;
    proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
  }
}
EOF
sudo nginx -t && sudo systemctl reload nginx
curl -sS -H 'Host: app.local' http://127.0.0.1/ -o /dev/null -w '%{http_code}\n'

sudo tee /etc/nginx/conf.d/demo.conf >/dev/null <<'EOF'
server {
  listen 8081;
  location / {
    proxy_pass http://127.0.0.1:8000;
    proxy_set_header Host $host;
    proxy_set_header X-Real-IP $remote_addr;
    proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
  }
}
EOF
sudo nginx -t && sudo systemctl reload nginx
python3 -m http.server 8000 & sleep 1
curl -s -o /dev/null -w '%{http_code}\n' http://127.0.0.1:8000/
curl -s -o /dev/null -w '%{http_code}\n' http://127.0.0.1:8081/
curl -sI http://127.0.0.1:8081/ | head
